fn bodyReport(request: []const u8, messages: []Message) h.Lines {
    var found: ?*Message = null;
    for (messages) |*message| {
        if (message.id.len > 0 and h.eq(message.id, request)) { found = message; break; }
    }
    if (found == null) {
        result.write("not found");
        return result;
    }
